CREATE TABLE `game_info` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `vendor_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '厂商编码',
  `vendor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '场馆名称',
  `game_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '游戏名称',
  `game_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '游戏CODE',
  `cate_id` bigint DEFAULT NULL COMMENT '游戏分类',
  `sub_cate_id` bigint DEFAULT NULL COMMENT '游戏小类',
  `logo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '封面',
  `sort` int DEFAULT NULL COMMENT '排序',
  `maintain` tinyint NOT NULL DEFAULT '0' COMMENT '维护状态',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `online_count` int DEFAULT NULL COMMENT '在线人数',
  `support_currency` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '支持的货币',
  `support_lang` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '支持的语言',
  `lang` json DEFAULT NULL COMMENT 'i18n',
  `remark` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人',
  `updater` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '操作人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `idx_t_game` (`game_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7926 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='游戏信息';

