CREATE TABLE `game_records` (
  `id` bigint NOT NULL COMMENT 'ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用户名',
  `action` tinyint DEFAULT NULL COMMENT '下单动作',
  `trace_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '三方请求流水号',
  `order_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '订单号',
  `ref_order_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '三方订单号',
  `round_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '局号',
  `room_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '房间号',
  `issue_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '局号期号',
  `bet_amount` decimal(18,2) DEFAULT NULL COMMENT '下注金额',
  `bet_content` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '投注内容',
  `win_loss` decimal(18,2) DEFAULT NULL COMMENT '输赢金额',
  `win_amount` decimal(10,0) DEFAULT '0' COMMENT '派彩金额',
  `extra_content` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '拓展内容',
  `create_time` datetime DEFAULT NULL COMMENT '订单的创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '订单更新时间',
  `vendor_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '厂商编码',
  `game_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '游戏编码',
  `game_kind` tinyint NOT NULL DEFAULT '1' COMMENT '游戏类型',
  `odds` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '赔率信息',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注信息',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标识',
  `tenant_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '租户编码',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户标识',
  `currency` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '货币标识',
  `jackpot_amount` decimal(10,2) DEFAULT NULL COMMENT '赠送金额',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_platform_draw` (`order_no`) USING BTREE,
  KEY `idx_user_time` (`create_time`) USING BTREE,
  KEY `idx_user_code` (`user_id`,`game_code`) USING BTREE,
  KEY `idx_agent_platform_draw` (`vendor_code`,`order_no`) USING BTREE,
  KEY `idx_game_code` (`game_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='用户游戏记录';

